import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AG stories, built with the shared `followUp` helper in FollowUpCasesAF.
extension FollowUpCases {
    static let batchAG: [CaseTemplate] = [
        roadRageBat, leagueThreats, pastureDog, surveyorRifle, motelHoldover, repoLot, barCarry, blockedInPistol, pumpCards, deckBreakIns
