    // MARK: - After the softball bat

    static let roadRageBat = followUp(
        key: "story.followup.roadRageBat", category: .violent,
        headlines: ["Driver Smashes Mirror With Bat in Traffic Dispute", "Bat Comes Out Again: Softball Case Defendant Charged in Road Rage"],
        law: "awdw", threshold: 5,
        spec: "Assaulted {V} with a deadly weapon, a softball bat, on {STREET}, on {DATE}.", victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} cut in front of {D} at a lane closure on {STREET} on {DATE}. At the next light {DL} got out with a bat, swung it at {V}'s open window, and smashed the side mirror when {V} pulled away. {V}'s dash camera recorded the swing and {DL}'s plate. {DL} says {D.he} swung at the mirror, never at {V}, and only after {V} brake-checked {D.him} twice.",
        state: [E(.video, 3, "Dash Camera", "{D} walks up with a bat and swings at the open driver's window as the car pulls away; the bat hits the mirror."),
                E(.physical, 2, "The Mirror", "The driver's side mirror on {V}'s car, shattered and hanging by its wire.")],
        defense: [E(.statement, 1, "Brake Checks", "{DL} says {V} slammed on the brakes twice in front of {D.him} before the light.")],
        witnessRole: "Patrol deputy",
        exam: [.direct("What does the dash camera show?", "\"{DL} getting out at the light with a bat and swinging at the driver's window as {V} pulls off. The bat catches the mirror.\""),
               .direct("How far was the bat from {V}?", "\"The window was down. A foot, maybe less, from {V.his} head.\""),
               .direct("How did the encounter begin?", "\"{V} cut in front of {DL} at a lane closure on {STREET}. At the next light, {DL} got out of the car carrying a bat and walked up to {V}'s open driver's window.\""),
               .direct("What happened to {V}'s car?", "\"The driver's side mirror was shattered and hanging by its wire. The bat struck it as {V} pulled away from the light.\""),
               .direct("How was {DL} identified?", "\"{V}'s dash camera recorded the swing and {DL}'s license plate. That is how we got to {DL} the same day.\""),
               .direct("What did {V}'s passenger tell you?", "\"That {DL} yelled, 'I'll do you like the last one,' as {D.he} swung. The passenger gave that statement a few days later.\""),
               .cross("The camera faces forward. It doesn't show any brake checks behind.", "\"No. It shows what's in front.\""),
               .cross("The only thing the bat touched was the mirror.", "\"Only because {V} drove off. The window was down, and a foot or less from {V.his} head is where that swing was headed.\""),
               .cross("{DL} says {V} brake-checked {D.him} twice?", "\"A second dash camera in the car behind {DL} shows exactly that, and it shows {V} making a rude gesture. I do not dispute it.\""),
               .cross("The bat did not touch {V}, did it?", "\"No. It touched the mirror, because {V} pulled away. A foot or less from {V}'s head is where the bat was when it swung.\""),
               .cross("{DL} has played ball for years, hasn't {D.he}?", "\"{DL} says {D.he} still plays, and that is why the bat was in the car. That would also make {D.him} someone who knows how to swing it.\"")],
        theory: ("{D} took a bat to another driver's open window over a lane change. The mirror took the hit only because {V} drove off.",
                 "{D} lost {D.his} temper and broke a mirror. That's damage to property, not an assault with a deadly weapon."),
        allocution: "\"I still play softball, and that bat is in my car all season. I swung it at the car after being cut off, and I smashed the mirror. I'm sorry that {V} was frightened, and I'm ashamed of losing my head. I'll pay for the mirror and keep the bat in the trunk.\"",
        truths: ("A passenger in {V}'s car later said {DL} yelled, \"I'll do you like the last one,\" as {D.he} swung.",
                 "A second dash camera, in the car behind {D}, showed {V} brake-checking {D.him} twice and flipping {D.him} off."),
        defendant: [.direct("Why did you have a bat in the car?", "\"I still play. It's in my car all season.\""),
               .direct("What did you swing at?", "\"The mirror. I wanted {V.him} to know {V.he} almost got somebody killed.\""),
               .direct("What happened at the lane closure?", "\"{V} cut in front of me and then slammed on the brakes twice. I had to stand on my own brakes, and I was shaking by the time we got to the light.\""),
               .direct("What did you do at the light?", "\"I got out with the bat in my hand, and I walked up to the window. I was angry, and I wanted {V.him} to see how close {V.he} came to causing a wreck.\""),
               .direct("What were you swinging at?", "\"The mirror. I never meant to hit {V}. I swung at the mirror because I wanted to break something and not hurt anyone.\""),
               .direct("What did {V} do after you swung?", "\"{V} sped off, and I stood there holding the bat. I realized what I had done and I put it back in the car.\""),
                    .cross("After your last case, you got out of your car with a bat.", "\"I know how it looks.\""),
               .cross("{V}'s window was open.", "\"I wasn't swinging at the window.\""),
               .cross("You said you would 'do {V.him} like the last one.'", "\"I said something like that, and it was a stupid thing to say. It was about a mailbox I had smashed years ago, not a person.\""),
               .cross("You walked up to a stranger's car with a bat.", "\"I did, and I should not have done that. After my earlier case I should have known better than to ever pick up a bat in anger.\""),
                    .cross("The bat broke a mirror a foot from {V}'s head.", "\"I know. I was not aiming at {V.him}, but I understand how close it was.\"")],
        openings: ("After {V} cut in front of {D} at a lane closure, {D} got out at the next light with a bat and swung it at {V}'s open window. The bat smashed the mirror as {V} pulled away, and {V}'s dash camera recorded the swing and {D}'s plate.", "The defense will say {V} brake-checked {D} twice and made a rude gesture, that {D} swung at the mirror and never at {V}, and that a second camera shows the provocation. This was damage to property in a moment of anger, not an assault."),
        closings: ("A bat, an open window a foot from {V}'s head, and a shattered mirror, all on camera. A passenger heard {D} yell, 'I'll do you like the last one,' and {D} already knew this courtroom from {PRIOR}.", "{V} cut in and brake-checked {D}, and a second camera proves it. {D} broke a mirror and never touched {V}, and the State must prove {D} meant to hurt a person and not to damage a mirror."),
        timeline: [(0, "Lane closure on {STREET}; {V} cuts in."), (0, "At the light, {D} swings a bat; mirror smashed."), (1, "{V} gives deputies the dash camera video.")],
        identified: "The dash camera caught {D}'s plate.",
        impact: "\"I have a three-year-old in the back seat most days. That day I didn't. I keep thinking about that.\"",
        doctrines: ["burdenOfProof", "lesserIncluded"])

    static let leagueThreats = followUp(
        key: "story.followup.leagueThreats", category: .publicOrder,
        headlines: ["Banned Player Charged With Threatening League Director", "League Director Says Voicemail Promised 'Your Turn'"],
        law: "communicatingThreats", threshold: 5,
        spec: "Willfully threatened to physically injure {V}, the director of a county recreation league, in a manner and under circumstances that would cause a reasonable person to believe the threat was likely to be carried out, on {DATE}.", victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the county recreation league banned {D} for life. On {DATE}, {V}, the league director, got a voicemail from {DL}'s number: \"You took my whole life away. You'll get your turn. I know where the fields are and I know when you lock up.\" {V} changed {V.his} schedule and asked for a deputy at the fields. {DL} says {D.he} was drunk and venting, and meant the lawsuit {D.he} planned to file.",
        state: [E(.digital, 3, "The Voicemail", "Forty seconds from {D}'s number: \"You took my whole life away. You'll get your turn. I know where the fields are and I know when you lock up.\""),
                E(.document, 2, "Ban Letter", "The league's letter to {DL} banning {D.him} from all county fields, mailed four days before the voicemail.")],
        defense: [E(.document, 1, "Lawyer Intake Form", "A form {DL} filled out at a civil lawyer's office the next day, asking about suing the league.")],
        witnessRole: "Sheriff's investigator",
        exam: [.direct("What did you do after {V} called you?", "\"Listened to the voicemail, confirmed the number was {DL}'s, and sent a deputy to the fields for the next two weeks.\""),
               .direct("Did {DL} deny leaving it?", "\"No. {D.He} said {D.he}'d been drinking and was angry.\""),
               .direct("What was {V}'s position?", "\"{V} is the director of the county recreation league. {V.he} runs the schedule, the fields and the discipline of coaches and players.\""),
               .direct("Why was {DL} banned?", "\"After the earlier case, the league banned {D.him} for life from all county fields. The ban letter was mailed four days before the voicemail.\""),
               .direct("What did the voicemail say?", "\"'You took my whole life away. You'll get your turn. I know where the fields are and I know when you lock up.' It runs forty seconds, and it came from {DL}'s number.\""),
               .direct("What did you find on {DL}'s phone?", "\"A search showed {D.he} had looked up {V}'s home address the same night, a few minutes after the voicemail was left.\""),
               .cross("{DL} never went near the fields.", "\"Not that we saw. We never saw {D.him} near the fields.\""),
               .cross("'You'll get your turn' could mean a lawsuit.", "\"Not with 'I know when you lock up' after it.\""),
               .cross("{DL} said {D.he} was drunk?", "\"Yes, {DL} told me so. {D.He} did not deny leaving the voicemail and said the drinking was why it came out the way it did.\""),
               .cross("{DL} filled out a lawyer intake form the next day, didn't {D.he}?", "\"{DL} did, asking about suing the league. The form was dated the day after the voicemail.\""),
               .cross("{DL} never came to the fields, did {D.he}?", "\"We never saw {D.him} near them. I sent a deputy there for two weeks and he did not appear.\"")],
        theory: ("A person banned for hitting someone with a bat told the director {V.he}'d get {V.his} turn and that {D.he} knew when {V.he} locked up alone.",
                 "{D} was drunk and angry and talking about a lawsuit. Ugly words aren't a true threat."),
        allocution: "\"I left that voicemail in anger after being banned for life. I said I'd sue, and I said things I did not mean. I know it frightened {V}, and I'm sorry. I played in that league for years, and I'd never hurt anyone there. I'll go through the courts instead of the phone.\"",
        truths: ("A search of {DL}'s phone showed {D.he} had looked up {V}'s home address the same night.",
                 "{DL}'s sister later said {D.he} spent the whole next day talking about suing, not about {V}."),
        defendant: [.direct("What did you mean by 'your turn'?", "\"That I'd sue. That {V.he}'d have to answer for taking ball away from me.\""),
               .direct("Why mention when {V.he} locks up?", "\"I was drunk. It came out wrong.\""),
               .direct("What was your history with the league?", "\"I coached and played for years. After my earlier case the league banned me from every field in the county, and it felt like they took away the only thing I cared about.\""),
               .direct("What happened the night of the voicemail?", "\"I was drinking at home, and I was angry about the ban. I called the number and said things I would never say sober.\""),
               .direct("Why did you look up {V}'s address?", "\"I wanted to know where to send papers if I sued. That is the only reason, and I never went there.\""),
               .direct("What happened after you left the voicemail?", "\"I fell asleep, and the next day I regretted it. I did not call again, and I did not go near the fields.\""),
                    .cross("You'd just been banned for hitting someone with a bat.", "\"That's why it came out wrong.\""),
               .cross("Would you have been afraid, getting that voicemail?", "\"Probably, yes. I'd have been afraid if I'd gotten that voicemail.\""),
               .cross("You said you know when {V.he} locks up.", "\"That was the drinking. I know when the fields lock because I used to work there, and it came out wrong.\""),
               .cross("The voicemail would frighten anybody.", "\"It would, and I understand that now. I am sorry that {V} was afraid, and I did not intend that.\""),
               .cross("You looked up {V}'s address that same night.", "\"I did, and I told you why. I wanted to know where to send papers, and I never drove there.\"")],
        openings: ("After the league banned {D} for life, {V}, the league director, got a forty-second voicemail from {D}'s number: 'You'll get your turn. I know where the fields are and I know when you lock up.' {V} changed {V.his} schedule and asked for a deputy at the fields.", "The defense will say {D} was drunk, angry about the ban, and talking about a lawsuit. 'Your turn' meant a court date, and {D} never went near the fields."),
        closings: ("The voicemail names the fields and when {V} locks up, {D}'s phone searched for {V}'s home address that night, and {D} had just been banned over {PRIOR}. A reasonable person would be afraid.", "{D} was drunk, banned, and thinking about suing, and the next day filled out a lawyer's intake form. The State must prove {D} meant to threaten and not merely to rant, and {D} never came near the fields."),
        timeline: [(-4, "League mails {DL} a lifetime ban."), (0, "Late night: voicemail to {V}."), (1, "{DL} visits a civil lawyer; {V} reports the voicemail.")],
        identified: "The voicemail came from {DL}'s phone number.",
        impact: "\"I lock up those fields alone four nights a week. For two weeks I had a deputy walk me to my car. I've coached kids there for twenty years.\"")

    // MARK: - After the shots at the farm gate

    static let pastureDog = followUp(
        key: "story.followup.pastureDog", category: .publicOrder,
        headlines: ["Farmer Charged After Shooting Neighbor's Dog", "Neighbor Says Dog Was Shot on the Road, Not in the Pasture"],
        law: "animalCruelty", threshold: 5,
        spec: "Maliciously killed a dog belonging to {V} by shooting it, on {DATE}.", ages: 52...72, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shot and killed {V}'s Labrador on {DATE}. {DL} says the dog was in {D.his} pasture chasing a calf, which a farmer may lawfully stop. {V} says the dog was on the road shoulder, walking home, and the body was found in the ditch outside the fence. A calf in the pasture had a torn ear.",
        state: [E(.physical, 3, "Where the Dog Lay", "The dog was found in the ditch outside {DL}'s fence, about fifteen feet from the road. Blood was on the shoulder, not inside the fence."),
                E(.forensic, 2, "Necropsy", "One rifle round entered the left side. The veterinarian says the dog would have dropped within a few steps.")],
        defense: [E(.physical, 2, "Torn Ear", "A veterinarian's note on a calf in the pasture with a fresh tear to the ear consistent with a dog bite.")],
        witnessRole: "Animal control officer",
        exam: [.direct("Where was the dog?", "\"In the ditch outside the fence, with blood on the shoulder of the road. A shot dog doesn't jump a four-strand wire fence.\""),
               .direct("What did {DL} tell you?", "\"That the dog was after a calf and {D.he} shot it in the pasture.\""),
               .direct("What did the necropsy show?", "\"One rifle round entered the left side. The veterinarian says the dog would have dropped within a few steps of being hit.\""),
               .direct("What did you find at the scene?", "\"Blood on the road shoulder and the body in the ditch, about fifteen feet from the road. There was no blood inside the fence.\""),
               .direct("What about the calf?", "\"A veterinarian noted a fresh tear to a calf's ear in the pasture, consistent with a dog bite. I cannot say which dog or when it happened.\""),
               .direct("Was there any sign of a struggle in the pasture?", "\"Not that I could see. The grass was flat near the fence line, but I could not tell whether that came from a dog or the calves.\""),
                    .cross("A calf had a fresh dog bite on its ear.", "\"It did. I can't tell you which dog or when.\""),
               .cross("Could the dog have gone under the fence?", "\"The bottom wire is about a foot up. I can't rule it out.\""),
               .cross("A shot dog can run a short way, can't it?", "\"It can for a few steps. A four-strand fence with the bottom wire a foot up is not something a dog hit like that jumps.\""),
               .cross("A game camera shows the dog in the pasture, doesn't it?", "\"It does. The camera on the fence line shows the dog inside the pasture chasing the calf two minutes before the shot.\""),
               .cross("A school bus driver saw the dog on the shoulder?", "\"She says she saw it walking the shoulder seconds before the shot. That is also what {V} says, and the two accounts do not fit together neatly.\"")],
        theory: ("{D} shot a neighbor's dog on the road shoulder and claimed it was after {D.his} cattle.",
                 "The dog had been at {D.his} calves; a farmer may stop a dog attacking livestock. Where it fell after the shot proves nothing."),
        allocution: "\"That dog had a calf down by the ear, and I've lost calves to dogs before. I shot it because I thought I was protecting my herd. I'm sorry that it was {V}'s Labrador, and I know it was loved. I'll pay for the loss and apologize to the family.\"",
        truths: ("A school bus driver later said she saw the dog walking the shoulder seconds before the shot.",
                 "A game camera on the fence line showed the dog inside the pasture, chasing the calf, two minutes before the shot."),
        defendant: [.direct("Why did you shoot the dog?", "\"It had a calf down by the ear. I've lost calves to dogs before.\""),
               .direct("Where was it when you fired?", "\"In the pasture, running for the fence.\""),
               .direct("What is your farm like?", "\"I raise calves, about forty head, on a pasture that runs along the road. I have lost calves to dogs before, and I keep a rifle handy.\""),
               .direct("What did you see that day?", "\"The Labrador was in my pasture, running after a calf. It had the calf down by the ear, and I did not have time to call anyone.\""),
               .direct("Why did you shoot?", "\"A farmer may stop a dog that is attacking his livestock. I fired one round at the dog while it had the calf, and I did not want it to go after another.\""),
               .direct("Where was the dog when you fired?", "\"In the pasture, running for the fence. After I shot, it ran toward the road, and I did not see where it fell until later.\""),
               .cross("It was found outside the fence, on the road side.", "\"It ran after I shot it.\""),
               .cross("You could have called animal control.", "\"And watched my calf get torn up while I waited?\""),
               .cross("The dog was found outside your fence, in the ditch.", "\"It must have gone under or through the fence after I shot it. I did not see where it ended up.\""),
               .cross("The bus driver saw the dog on the shoulder.", "\"She may have seen a dog on the shoulder earlier. I saw this dog in my pasture, and the camera on the fence shows it there.\""),
                    .cross("You never saw the dog bite the calf yourself.", "\"I saw it with the calf down by the ear. I did not wait around to count teeth marks.\"")],
        openings: ("{D} shot and killed {V}'s Labrador. {V} says the dog was walking home on the road shoulder, and the body was found in the ditch outside {D}'s fence, with blood on the shoulder and none inside the fence.", "The defense will say the dog was inside the pasture with a calf down by the ear, and a game camera shows it there two minutes before the shot. A farmer may lawfully stop a dog attacking livestock."),
        closings: ("The dog lay in the ditch outside the fence, blood on the shoulder and none in the pasture, and {PRIOR} had already brought {D} before this court once. A shot Labrador does not clear a four-strand fence.", "A game camera shows the dog chasing the calf, and a calf had a torn ear. A farmer who stops a dog attacking his livestock acts lawfully, and the State must prove {D} shot a dog that was not."),
        timeline: [(0, "Evening: {DL} shoots the dog; {V} finds it in the ditch."), (0, "Animal control photographs the scene and the calf.")],
        identified: "{DL} told the animal control officer {D.he} shot the dog.",
        impact: "\"She was eleven. My kids grew up with her. She'd walk the road home from the creek every evening. Everybody on that road knew her.\"",
        doctrines: ["burdenOfProof", "justification"])

    static let surveyorRifle = followUp(
        key: "story.followup.surveyorRifle", category: .violent,
        headlines: ["Farmer Points Rifle at Power Line Surveyor", "Surveyor Says Farmer Raised Rifle at the Property Line"],
        law: "assaultPointingGun", threshold: 5,
        spec: "Pointed a rifle at {V}, a land surveyor working on a utility easement, on {DATE}.", ages: 52...72, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a surveyor marking a power line easement that crosses {D}'s back field, was setting a stake on {DATE} when {DL} drove up on a tractor with a rifle. {V} says {DL} raised the rifle and told {V.him} to get off the land. {V}'s partner filmed part of it. {DL} says the rifle stayed pointed at the ground and {D.he} was carrying it for coyotes.",
        state: [E(.video, 3, "Partner's Video", "Twelve seconds: {D} on the tractor seat, rifle across {D.his} lap, then raised to {D.his} shoulder as {D.he} shouts, \"Off my land.\" The barrel's direction is hard to judge from the angle."),
                E(.document, 2, "Easement Record", "A recorded easement giving the power company the right to survey and maintain the line across {DL}'s field.")],
        defense: [E(.statement, 1, "Coyotes", "Two neighbors say coyotes have taken calves on Shiloh Road this year and farmers carry rifles in the fields.")],
        witnessRole: "Sheriff's investigator",
        exam: [.direct("What does the video show?", "\"The rifle comes off {DL}'s lap and up to {D.his} shoulder. {V} says it was pointed at {V.him}.\""),
               .direct("Did {V} have a right to be there?", "\"Yes. The easement is recorded, and the company sent {DL} a letter two weeks before.\""),
               .direct("What was {V} doing that day?", "\"{V} was setting a stake for a power line easement that crosses {DL}'s back field. The easement is recorded, and the power company sent {DL} a letter two weeks before.\""),
               .direct("What happened when {DL} drove up?", "\"{DL} came up on a tractor with a rifle across {D.his} lap. {V} says {DL} raised the rifle and told {V.him} to get off the land.\""),
               .direct("Why were coyotes mentioned?", "\"Two neighbors say coyotes have been taking calves on that farm, and that {DL} carries a rifle on the tractor for that reason.\""),
               .direct("What happened after {DL} lowered the rifle?", "\"The surveyors left the field and called us from the road. No shot was fired, and {DL} stayed on the tractor.\""),
                    .cross("You can't tell from the angle where the barrel pointed.", "\"Not exactly. It's up, and it's toward {V}'s side of the field.\""),
               .cross("Farmers out there carry rifles for coyotes.", "\"They do. They don't usually shoulder them at surveyors.\""),
               .cross("The video was taken from an angle, wasn't it?", "\"Yes. From where the partner stood, I cannot tell you for certain where the barrel pointed. It is up, and it is toward the surveyor's side of the field.\""),
               .cross("The partner has a second, longer video, doesn't {V.he}?", "\"There is a longer one. In my review it shows the barrel tilted above {V}'s head, toward the tree line, though the angle is not perfect.\""),
               .cross("{DL} never fired the rifle?", "\"No shot was fired. {DL} lowered the rifle after yelling, and the surveyors left the field.\"")],
        theory: ("{D}, whose case over shots fired at a truck at {D.his} gate this court already heard, raised a rifle at a surveyor doing lawful work.",
                 "{D} carries a rifle for coyotes. {D.He} lifted it while yelling, but never aimed it at anyone."),
        allocution: "\"I drove up on my tractor yelling and waving, and the rifle was in my hands. I never put my eye to it. I was angry about the easement and I did not think. I'm sorry that I frightened {V}, who was only doing a job. I'll put the rifle away and talk to the power company.\"",
        truths: ("{V}'s partner's second, longer video showed the barrel level with {V}'s chest.",
                 "The partner's second, longer video showed the barrel tilted well above {V}'s head, toward the tree line."),
        defendant: [.direct("Why did you lift the rifle?", "\"I was yelling and waving. It was in my hands. I never put my eye to it.\""),
               .direct("Did you know about the easement?", "\"I knew there was one. I didn't know they were coming that day.\""),
               .direct("Why were you carrying a rifle?", "\"Coyotes have been taking my calves, and I carry a rifle on the tractor every day. It was across my lap when I saw the surveyors.\""),
               .direct("Why did you drive up to them?", "\"I saw people in my back field with stakes and I did not know who they were. I wanted to know what they were doing on my land.\""),
               .direct("What did you do with the rifle?", "\"I lifted it because I was yelling and waving. I never put my eye to the sight, and I never pointed it at anybody.\""),
               .direct("What did you say to the surveyors?", "\"'Off my land.' I yelled it, and I waved. I did not say I would hurt anyone.\""),
                    .cross("The company sent you a letter two weeks earlier.", "\"I don't open their letters.\""),
               .cross("After what happened at your gate, you picked up a rifle at a stranger again.", "\"I know how that sounds.\""),
               .cross("After the case about your gate, you picked up a rifle at strangers again.", "\"I know how that sounds. I should have left the rifle on the seat, and I was trying to scare off coyotes, not people.\""),
               .cross("The barrel came up toward {V}'s side of the field.", "\"It came up as I waved my arms. If it pointed at {V}, that was not on purpose.\""),
               .cross("You raised the rifle while yelling at people on an easement.", "\"I did, and I should not have. I was not thinking about the law. I was thinking about my land.\"")],
        openings: ("{V}, a surveyor, was marking a recorded power line easement across {D}'s back field when {D} drove up on a tractor with a rifle, raised it to {D.his} shoulder, and shouted, 'Off my land.' {V}'s partner filmed twelve seconds of it.", "The defense will say {D} carries a rifle on the tractor for coyotes, lifted it while yelling, and never aimed it at anyone. The partner's longer video shows the barrel above {V}'s head."),
        closings: ("A rifle raised to the shoulder, a shouted order to get off the land, and a recorded easement. After the earlier shots at {D}'s gate over {PRIOR}, {D} knew exactly what raising a rifle at strangers means.", "{D} was yelling and waving with a coyote rifle already in hand, and no shot was fired. The longer video shows the barrel tilted toward the trees, and the State must prove {D} pointed it at {V}."),
        timeline: [(-14, "Power company mails {DL} notice of the survey."), (0, "Morning: {V} staking the easement; {DL} arrives with a rifle."), (0, "{V} and {V.his} partner report it.")],
        identified: "{V} knew {DL} from the easement paperwork; the partner's video.",
        impact: "\"I've been surveying for twenty-two years. I've been chased by dogs and yelled at plenty. Nobody has ever put a rifle up at me. I froze.\"")

    // MARK: - After the lockout

    static let motelHoldover = followUp(
        key: "story.followup.motelHoldover", category: .publicOrder,
        headlines: ["Motel Guest Charged With Trespass After Refusing to Leave", "Tenant From Lockout Case Charged at Extended-Stay Motel"],
        law: "trespass2", threshold: 5,
        spec: "Remained in a room at {PLACE.MOTEL} after being notified not to remain there by the owner, on {DATE}.", victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} and {D.his} son moved into a weekly room at {PLACE.MOTEL}. On {DATE}, with the week unpaid, the manager told {DL} to leave by noon. {D.He} refused, saying {D.he} had lived there more than a month and could only be evicted through the court. Deputies arrested {D.him} at 2 p.m. {DL}'s defense is that a long-term motel resident is a tenant, not a guest.",
        state: [E(.document, 3, "Registration Card", "The card {DL} signed: \"Transient guest. Weekly rate. Room must be vacated at checkout if unpaid.\""),
                E(.statement, 2, "Manager's Notice", "The manager told {DL} at 9 a.m. to leave by noon, and again at 1 p.m. in front of a housekeeper.")],
        defense: [E(.document, 2, "Rent Receipts", "Five weekly receipts for the same room, and a school enrollment form for {DL}'s son listing the motel as his home address.")],
        witnessRole: "Patrol deputy",
