        doctrines: ["burdenOfProof", "mistakeOfFact"])

    static let repoLot = followUp(
        key: "story.followup.repoLot", category: .property,
        headlines: ["Owner Charged With Stealing Back Repossessed Car", "Repossessed Car Driven Off Lot With Spare Key"],
        law: "felonyLarceny", lesser: "misdLarceny",
        spec: "Took and carried away a car, valued at $6,400, from the lawful possession of a repossession company holding it for the lienholder, on {DATE}.", victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}'s car was repossessed for three missed payments. On {DATE}, {DL} walked into the repossession company's lot after hours through an open gate and drove the car away with a spare key. The lot's camera recorded it. The car was found in {D.his} driveway the next morning. {DL} says it's {D.his} car, the title is in {D.his} name, and {D.he} needed it to get to work.",
        state: [E(.video, 3, "Lot Camera", "{D} walks through the open gate at 10:40 p.m., unlocks the car with a key, and drives off."),
                E(.document, 2, "Loan Contract", "The lender's lien on the title, the default notices, and the repossession order to the lot.")],
        defense: [E(.document, 2, "Title", "The North Carolina title in {DL}'s name, with the lender listed as lienholder.")],
        witnessRole: "Property crimes detective",
        exam: [.direct("Whose car was it?", "\"Titled to {DL}, with a lien. Once the lender repossessed it after default, the lender had the right to possess it.\""),
               .direct("What did the camera show?", "\"{DL} walking in at 10:40 p.m. and driving out with a key.\""),
               .direct("Why was {DL}'s car repossessed?", "\"{DL} missed three payments. The lender sent default notices and gave the repossession order to the lot, which took the car.\""),
               .direct("Where was the car found?", "\"In {DL}'s driveway the next morning. {DL} had not tried to hide it, which is why we found it so quickly.\""),
               .direct("What did the lender's letter say?", "\"It explained how to redeem the car by paying the balance due and fees. {DL} never made that payment.\""),
               .direct("Did {DL} have a key to the car?", "\"A spare key, which {DL} used to unlock it on the camera. The lender had the original on file.\""),
                    .cross("The title is in {DL}'s name.", "\"It is. The right to hold it was the lender's.\""),
               .cross("Did anyone tell {DL} {D.he} couldn't get it back?", "\"The lender's letter said how to redeem it: pay the balance due and fees.\""),
               .cross("The gate was open?", "\"Yes. The lot's gate had been left open that night. {DL} walked in without breaking anything.\""),
               .cross("{DL} called the lender the next morning?", "\"{DL} says so, and the lender's records show a call to arrange payment before anyone contacted {D.him}.\""),
                    .cross("{DL} did not break anything to get in?", "\"No. The gate was open, and the car was unlocked with a key.\"")],
        theory: ("Once the car was lawfully repossessed, {D} had no right to take it back without paying. {D.He} took it anyway.",
                 "{D} took {D.his} own car, titled in {D.his} name. You can't steal what you own."),
        allocution: "\"It's my car, and my name is on the title. I needed it to get to work or I'd lose my job too. I walked into that lot through an open gate and used a spare key, and I know that was wrong. I'm sorry to the repossession company. I'll work out a payment plan.\"",
        truths: ("{DL} told a coworker {D.he} was going to \"hide it at my cousin's till they give up.\"",
                 "{DL} called the lender the next morning to arrange payment before anyone contacted {D.him}."),
        defendant: [.direct("Why did you take the car?", "\"It's my car. My name's on the title. I needed it to get to work or I'd lose that too.\""),
               .direct("Did you think it was stealing?", "\"No. How can you steal your own car?\""),
               .direct("How did you get in?", "\"The gate was open and I had a spare key. I walked in and drove out, and I did not break anything.\""),
               .direct("Why did you go at night?", "\"That is when I got off work. I did not have a way to get there earlier, and I was not trying to hide.\""),
               .direct("What did you do after you took the car?", "\"I parked it in my driveway and called the lender in the morning. I wanted to arrange payment and keep the car.\""),
               .direct("What did you tell the lender the next morning?", "\"That I had the car and wanted to work out a payment. I was not hiding it from anyone.\""),
                    .cross("You'd missed three payments.", "\"Yes. I'd missed three payments, and I know the account was behind.\""),
               .cross("You went in at night, after hours.", "\"That's when I got off work.\""),
               .cross("You told a coworker you would hide it at your cousin's.", "\"I said something like that when I was angry. I did not hide it. It was in my driveway the next morning.\""),
               .cross("The lender had the right to possess the car.", "\"I understand that now. I was behind, and I did not think taking my own car was stealing.\""),
               .cross("The lender's letter told you how to redeem the car.", "\"I read it, and I did not have the money. I thought I could work something out after I had the car back.\"")],
        openings: ("After {D} missed three payments, the lender repossessed {D}'s car and held it at a lot. At 10:40 p.m. {D} walked through an open gate with a spare key and drove it away, and the lot camera recorded it.", "The defense will say the title is in {D}'s name and no one can steal what {D.he} owns. {D} took the car back openly, parked it in {D.his} driveway, and called the lender the next morning."),
        closings: ("Once the lender repossessed the car, the lender had the right to hold it until {D} paid. {D} went onto the lot at night with a spare key, and after {PRIOR} {D} knew what a repossession means.", "The title is in {D}'s name, the gate was open, and {D} left the car in {D.his} driveway and called the lender. The State must prove {D} meant to take what was not {D.his}."),
        timeline: [(-10, "Car repossessed after three missed payments."), (0, "10:40 p.m.: {DL} drives the car off the lot."), (1, "Car found in {DL}'s driveway.")],
        identified: "The lot camera and the car in {DL}'s driveway.",
        doctrines: ["burdenOfProof", "mistakeOfFact"])

