    static let barCarry = followUp(
        key: "story.followup.barCarry", category: .publicOrder,
        headlines: ["Former Bar Guard Charged With Carrying While Drinking", "Gun Found on Drinking Patron Was Former Bouncer's"],
        law: "concealedWeapon", threshold: 4,
        spec: "Carried a concealed handgun while consuming alcohol, at {BAR}, on {DATE}.", victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was at {BAR} on {DATE} when a fight broke out near the pool table. A deputy breaking it up saw a holstered pistol under {DL}'s shirt. {D.He} had two beers on {D.his} tab. A concealed handgun permit doesn't allow carrying while drinking. {DL} says {D.he} had one sip of the second beer and wasn't impaired.",
        state: [E(.document, 3, "Bar Tab", "Two draft beers on {DL}'s tab in the hour before the fight."),
                E(.physical, 2, "The Pistol", "A 9mm pistol in an inside-the-waistband holster, loaded, taken from {DL}.")],
        defense: [E(.document, 1, "Permit", "{DL}'s current concealed handgun permit.")],
        witnessRole: "Patrol deputy",
        exam: [.direct("How did you find the pistol?", "\"Breaking up the fight, {DL}'s shirt rode up and I saw the holster.\""),
               .direct("Was {DL} drinking?", "\"Two beers on the tab, a half-empty glass in front of {D.him}. {D.He} told me {D.he}'d had 'a couple.'\""),
               .direct("What was the call at the bar?", "\"A fight had broken out near the pool table, and I was one of the deputies sent to break it up. Several people were shouting and a bottle had been thrown.\""),
               .direct("How did you see the pistol?", "\"While I was separating two men, {DL} was standing nearby at the bar, and {D.his} shirt rode up when {D.he} reached for a glass. I saw a holster.\""),
               .direct("What kind of firearm was it?", "\"A 9mm pistol in an inside-the-waistband holster. It was loaded, with a round in the chamber, and I took it from {DL} for safety.\""),
               .direct("What did the bar tab show?", "\"Two draft beers on {DL}'s tab in the hour before the fight. A half-empty glass sat in front of {D.him} when I arrived.\""),
               .cross("{DL} wasn't in the fight.", "\"No. {D.He} was at the bar.\""),
               .cross("You didn't test {D.his} blood alcohol.", "\"The law doesn't require impairment. It's carrying while consuming.\""),
               .cross("{DL} had a valid permit, didn't {D.he}?", "\"Yes, a current concealed handgun permit. The permit is not the issue. The issue is that the law forbids carrying a concealed handgun while consuming alcohol.\""),
               .cross("You never saw {DL} drink the second beer?", "\"No. I saw a half-empty glass and two beers on the tab, and {DL} told me {D.he} had 'a couple.' I did not watch the drinks being poured.\""),
               .cross("{DL} stayed out of the fight, didn't {D.he}?", "\"{D.He} did. {D.He} never touched the pistol and did not join the fight. That does not change the law about carrying while drinking.\"")],
        theory: ("{D} carried a loaded pistol at a bar while drinking. The law forbids it, impaired or not.",
                 "{D} had a permit and wasn't impaired. The State can't show {D.he} drank the second beer."),
        allocution: "\"I carry that pistol because people have threatened me, and I don't go anywhere without it. I had two beers on my tab, and I did not think about the rule. I'm sorry for bringing it into a bar where a fight broke out. I'll leave it at home when I go out.\"",
        truths: ("The bartender later said {DL} finished both beers and ordered a third right before the fight.",
                 "The bartender later said the second beer on the tab was poured for {DL}'s friend."),
        defendant: [.direct("Why were you carrying?", "\"After what happened, people have threatened me. I don't go anywhere without it.\""),
               .direct("How much did you drink?", "\"One beer. The second one was mostly for show.\""),
               .direct("Why do you carry a pistol?", "\"After my earlier case, people have threatened me, and I don't go anywhere without it. I have a permit and I have taken the class.\""),
               .direct("What happened at the bar that night?", "\"I stopped in after work for a beer. A fight started across the room, and I stayed where I was at the bar. I did not want any part of it.\""),
               .direct("How many beers did you have?", "\"One. The second beer was ordered for a friend who had stepped away, and it sat on the bar. I never finished it.\""),
               .direct("Did you know the law about carrying while drinking?", "\"I knew about the rule. I did not think one beer counted, and I was not impaired. I am not trying to excuse it, only to tell you what I thought.\""),
               .cross("Both beers were on your tab.", "\"I paid for them. That doesn't mean I drank them.\""),
               .cross("You've been in court once already over a gun at a bar.", "\"That was work. I was carrying it because of my job at the time.\""),
               .cross("You told the deputy you had 'a couple.'", "\"I said that loosely. I meant I had been there a while, and I did not stop to count in the middle of a fight.\""),
               .cross("You have been in court over a gun at a bar before.", "\"That was different. I was carrying for my job at the time, and I had a reason. This time I should have left the pistol at home.\""),
                    .cross("You knew the permit rules say not to carry while drinking.", "\"I knew the rule. I did not think I was breaking it with one beer, and I should have left the pistol at home.\"")],
        openings: ("During a fight near the pool table at a bar, a deputy saw a holstered pistol under {D}'s shirt. {D} had two beers on the tab and a half-empty glass, and {D.he} told the deputy {D.he} had 'a couple.' A concealed handgun permit does not allow carrying while drinking.", "The defense will say {D} had a valid permit, had one beer, and stayed out of the fight. The second beer on the tab was poured for a friend, and the State cannot show {D} drank it."),
        closings: ("A loaded 9mm under a shirt, two beers on the tab, a half-empty glass, and {D}'s own words, 'a couple.' {D} had already been here over {PRIOR}, and {D.he} knew the law about carrying while drinking.", "{D} had a permit, took one beer, and never touched the pistol during the fight. The bartender says the second beer was poured for a friend, and the State must prove {D} drank it."),
        timeline: [(0, "Evening: {DL} at {BAR}; two beers on the tab."), (0, "Fight near the pool table; deputy finds the pistol.")],
        identified: "Found by the deputy at the scene.",
        extras: ["BAR": ["The Anchor Tavern", "Rooster's on Main", "The Tap Room"]])

    static let blockedInPistol = followUp(
        key: "story.followup.blockedInPistol", category: .violent,
        headlines: ["Shopper Pulls Pistol on Driver Who Blocked a Truck In", "Parking Dispute Ends With Gun Pointed Through Windshield"],
        law: "assaultPointingGun", threshold: 5,
        spec: "Pointed a handgun at {V}, in the parking lot of {PLACE.GROCERY}, on {DATE}.", victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} double-parked behind {D}'s truck at {PLACE.GROCERY} on {DATE} to run in for a prescription. When {V} came back, {DL} was waiting. {V} says {DL} yelled, then drew a pistol and pointed it at {V} through the windshield. {DL} says {D.he} showed the holstered gun only after {V} got out swinging a tire iron.",
        state: [E(.video, 3, "Store Camera", "{D} and {V} by {V}'s car; {D}'s right hand comes up level toward {V}. {V}'s hands are not visible behind the car door."),
                E(.statement, 2, "Cart Attendant", "A cart attendant says {D} \"pulled a gun and held it on the driver.\"")],
        defense: [E(.physical, 1, "Tire Iron", "A tire iron on the floor of {V}'s back seat.", .search)],
